import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '예산·회계 담당자';
// 가정: 쪽 크기 기본 20, 최대 200
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
// 가정: 장부 종류 값은 명세에 목록이 없어 문서에 나온 이름을 그대로 쓴다
const LEDGER_TYPES = ['자금출납장', '은행이체명세서', '지출원인행위부', '수입징수부'];
const SCOPES = ['전체', '금융기관별', '프로젝트별', '결의 담당자별'];
const VIEW_FORMS = ['상세', '총괄'];
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;
const ID_PATTERN = /^\d+$/;

type Params = Record<string, unknown>;

interface Plan {
  from: string;
  detail: string;
  order: string;
  group: string;
  groupSelect: string;
  params: Params;
}

const BANK_FROM = `FROM bank_transaction bt
  JOIN partner_account pa ON pa.partner_account_id = bt.partner_account_id
  LEFT JOIN journal_voucher jv ON jv.journal_voucher_id = bt.journal_voucher_id
  LEFT JOIN expense_resolution er ON er.expense_resolution_id = jv.expense_resolution_id
  WHERE bt.transaction_at >= CAST(:dateFrom AS date)
    AND bt.transaction_at < CAST(:dateTo AS date) + 1
    AND (CAST(:partnerAccountId AS bigint) IS NULL OR bt.partner_account_id = CAST(:partnerAccountId AS bigint))
    AND (CAST(:projectId AS bigint) IS NULL OR er.project_id = CAST(:projectId AS bigint))
    AND (CAST(:authorId AS bigint) IS NULL OR er.author_id = CAST(:authorId AS bigint))`;

const BANK_DETAIL = `bt.bank_transaction_id AS "bankTransactionId",
  bt.transaction_at AS "transactionAt",
  pa.bank_name AS "bankName",
  er.project_id AS "projectId",
  er.author_id AS "authorId",
  bt.summary AS "summary",
  bt.deposit_amount AS "depositAmount",
  bt.withdrawal_amount AS "withdrawalAmount",
  bt.balance_amount AS "balanceAmount",
  bt.processing_type AS "processingType"`;

const BANK_SUMS = `COUNT(*) AS "count",
  COALESCE(SUM(bt.deposit_amount), 0) AS "depositAmount",
  COALESCE(SUM(bt.withdrawal_amount), 0) AS "withdrawalAmount"`;

const BANK_GROUPS: Record<string, [string, string]> = {
  '금융기관별': ['pa.bank_name AS "bankName"', 'pa.bank_name'],
  '프로젝트별': ['er.project_id AS "projectId"', 'er.project_id'],
  '결의 담당자별': ['er.author_id AS "authorId"', 'er.author_id'],
};

const COMMITMENT_FROM = `FROM commitment c
  JOIN budget_item bi ON bi.budget_item_id = c.budget_item_id
  LEFT JOIN purchase_request pr ON pr.purchase_request_id = c.purchase_request_id
  WHERE c.created_at >= CAST(:dateFrom AS date)
    AND c.created_at < CAST(:dateTo AS date) + 1
    AND (CAST(:projectId AS bigint) IS NULL OR pr.project_id = CAST(:projectId AS bigint))`;

const REVENUE_FROM = `FROM expense_resolution er
  JOIN budget_item bi ON bi.budget_item_id = er.budget_item_id
  WHERE er.resolution_type = '수입'
    AND er.resolution_date >= CAST(:dateFrom AS date)
    AND er.resolution_date <= CAST(:dateTo AS date)
    AND (CAST(:projectId AS bigint) IS NULL OR er.project_id = CAST(:projectId AS bigint))
    AND (CAST(:authorId AS bigint) IS NULL OR er.author_id = CAST(:authorId AS bigint))`;

function text(value: unknown): string {
  return typeof value === 'string' ? value.trim() : '';
}

function idOf(value: unknown, label: string): string | null {
  const v = text(value);
  if (v === '') {
    return null;
  }
  if (!ID_PATTERN.test(v)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 형식이 올바르지 않습니다.');
  }
  return v;
}

function intOf(value: unknown, fallback: number, label: string): number {
  const v = text(value);
  if (v === '') {
    return fallback;
  }
  if (!ID_PATTERN.test(v)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 형식이 올바르지 않습니다.');
  }
  return Number(v);
}

function planOf(
  ledgerType: string,
  scope: string,
  base: Params,
  partnerAccountId: string | null,
  authorId: string | null,
): Plan {
  if (ledgerType === '자금출납장' || ledgerType === '은행이체명세서') {
    const key = ledgerType === '자금출납장' ? scope : '금융기관별';
    const [groupCol, groupBy] = BANK_GROUPS[key] ?? BANK_GROUPS['금융기관별'];
    return {
      from: BANK_FROM + (ledgerType === '은행이체명세서' ? ' AND bt.withdrawal_amount > 0' : ''),
      detail: BANK_DETAIL,
      order: 'bt.transaction_at, bt.bank_transaction_id',
      group: groupBy,
      groupSelect: groupCol + ', ' + BANK_SUMS,
      params: { ...base, partnerAccountId, authorId },
    };
  }
  if (ledgerType === '지출원인행위부') {
    // 지출원인행위에는 작성자·계좌가 없어 프로젝트만 연결 품의서를 통해 거른다 (가정)
    return {
      from: COMMITMENT_FROM,
      detail: `c.commitment_id AS "commitmentId",
  c.created_at AS "createdAt",
  c.commitment_type AS "commitmentType",
  c.budget_item_id AS "budgetItemId",
  bi.item_name AS "budgetItemName",
  c.partner_id AS "partnerId",
  c.amount AS "amount"`,
      order: 'c.created_at, c.commitment_id',
      group: 'c.budget_item_id, bi.item_name',
      groupSelect: `c.budget_item_id AS "budgetItemId",
  bi.item_name AS "budgetItemName",
  COUNT(*) AS "count",
  SUM(c.amount) AS "amount"`,
      params: { ...base },
    };
  }
  return {
    from: REVENUE_FROM,
    detail: `er.expense_resolution_id AS "expenseResolutionId",
  er.document_no AS "documentNo",
  er.resolution_date AS "resolutionDate",
  er.project_id AS "projectId",
  er.author_id AS "authorId",
  er.budget_item_id AS "budgetItemId",
  bi.item_name AS "budgetItemName",
  er.partner_id AS "partnerId",
  er.amount AS "amount",
  er.approval_status AS "approvalStatus"`,
    order: 'er.resolution_date, er.expense_resolution_id',
    group: 'er.budget_item_id, bi.item_name',
    groupSelect: `er.budget_item_id AS "budgetItemId",
  bi.item_name AS "budgetItemName",
  COUNT(*) AS "count",
  SUM(er.amount) AS "amount"`,
    params: { ...base, authorId },
  };
}

@Controller('api/v1')
export class FnSfr00501Controller {
  @Get('/budget-ledgers')
  async listBudgetLedgers(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const q = checks.queryOf(req.query);
    const ledgerType = text(q['ledgerType']);
    const dateFrom = text(q['dateFrom']);
    const dateTo = text(q['dateTo']);
    if (ledgerType === '' || dateFrom === '' || dateTo === '') {
      throw new ApiError(422, 'LEDGER_CONDITION_MISSING', '장부 종류와 조회 기간을 입력해 주세요.');
    }
    if (!LEDGER_TYPES.includes(ledgerType)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '지원하지 않는 장부 종류입니다.');
    }
    if (!DATE_PATTERN.test(dateFrom) || !DATE_PATTERN.test(dateTo)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 기간은 YYYY-MM-DD 형식이어야 합니다.');
    }
    const scope = text(q['cashbookScope']) || '전체';
    if (!SCOPES.includes(scope)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '자금출납장 조회 구분이 올바르지 않습니다.');
    }
    const viewForm = text(q['viewForm']) || '상세';
    if (!VIEW_FORMS.includes(viewForm)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 형태는 상세 또는 총괄이어야 합니다.');
    }
    const partnerAccountId = idOf(q['partnerAccountId'], '거래처 계좌');
    const projectId = idOf(q['projectId'], '프로젝트');
    const authorId = idOf(q['authorId'], '작성자');
    const page = intOf(q['page'], 0, '쪽 번호');
    const size = Math.min(Math.max(intOf(q['size'], DEFAULT_SIZE, '쪽 크기'), 1), MAX_SIZE);
    const summary = ledgerType === '자금출납장' ? scope !== '전체' : viewForm === '총괄';
    const plan = planOf(ledgerType, scope, { dateFrom, dateTo, projectId }, partnerAccountId, authorId);
    return transaction(async (db) => {
      const countSql = summary
        ? `SELECT COUNT(*) AS "total" FROM (SELECT 1 ${plan.from} GROUP BY ${plan.group}) t`
        : `SELECT COUNT(*) AS "total" ${plan.from}`;
      const countRows = await db.query(countSql, plan.params);
      const total = Number(countRows[0]['total']);
      const rowSql = summary
        ? `SELECT ${plan.groupSelect} ${plan.from} GROUP BY ${plan.group} ORDER BY 1 LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)`
        : `SELECT ${plan.detail} ${plan.from} ORDER BY ${plan.order} LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)`;
      const rows = await db.query(rowSql, { ...plan.params, size, offset: page * size });
      return { items: [{ rows }], page, size, total };
    });
  }
}

