import { useState } from 'react';
import type { ReactNode } from 'react';
import {
  call,
  useData,
  Num,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Tiles,
  Field,
  Select,
  DateInput,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page, Column } from '../kit';

const PAGE_SIZE = 20;

const LEDGER_TYPES: [string, string][] = [
  ['자금출납장', '자금출납장'],
  ['은행이체명세서', '은행이체명세서'],
  ['지출원인행위부', '지출원인행위부'],
  ['수입징수부', '수입징수부'],
];

const SCOPES: [string, string][] = [
  ['전체', '전체'],
  ['금융기관별', '금융기관별'],
  ['프로젝트별', '프로젝트별'],
  ['결의 담당자별', '결의 담당자별'],
];

const VIEW_FORMS: [string, string][] = [
  ['상세', '상세'],
  ['총괄', '총괄'],
];

const LABELS: Record<string, string> = {
  bankTransactionId: '거래 번호',
  transactionAt: '거래일시',
  bankName: '은행명',
  projectId: '프로젝트',
  authorId: '작성자',
  summary: '적요',
  depositAmount: '입금액',
  withdrawalAmount: '출금액',
  balanceAmount: '잔액',
  processingType: '처리 구분',
  commitmentId: '원인행위 번호',
  createdAt: '등록일시',
  commitmentType: '원인행위 구분',
  budgetItemId: '예산과목',
  budgetItemName: '예산과목명',
  partnerId: '거래처',
  amount: '금액',
  expenseResolutionId: '결의서 번호',
  documentNo: '문서번호',
  resolutionDate: '결의일자',
  approvalStatus: '결재 상태',
  count: '건수',
};

const REFS: Record<string, string> = {
  projectId: 'project',
  authorId: 'employee',
  budgetItemId: 'budget_item',
  partnerId: 'partner',
};

const AMOUNTS = ['depositAmount', 'withdrawalAmount', 'balanceAmount', 'amount', 'count'];
const TIMES = ['transactionAt', 'createdAt'];
const DATES = ['resolutionDate'];

interface Cond {
  ledgerType: string;
  dateFrom: string;
  dateTo: string;
  cashbookScope: string;
  viewForm: string;
  partnerAccountId: number | string;
  projectId: number | string;
  authorId: number | string;
}

const EMPTY: Cond = {
  ledgerType: '',
  dateFrom: '',
  dateTo: '',
  cashbookScope: '전체',
  viewForm: '상세',
  partnerAccountId: '',
  projectId: '',
  authorId: '',
};

function cellOf(key: string, value: unknown, role: string): ReactNode {
  if (value === null || value === undefined || value === '') {
    return '-';
  }
  if (REFS[key]) {
    return <RefName table={REFS[key]} role={role} value={value} />;
  }
  if (AMOUNTS.includes(key)) {
    return <Num value={value} />;
  }
  if (TIMES.includes(key)) {
    return <DateText value={value} time />;
  }
  if (DATES.includes(key)) {
    return <DateText value={value} />;
  }
  return String(value);
}

export default function FnSfr00501Page({ role, notify }: PageProps) {
  const [form, setForm] = useState<Cond>(EMPTY);
  const [applied, setApplied] = useState<Cond | null>(null);
  const [page, setPage] = useState(0);
  const [message, setMessage] = useState('');
  const [detail, setDetail] = useState<Row | null>(null);

  const { data, error, loading } = useData<Page | undefined>(() => {
    if (!applied) {
      return Promise.resolve(undefined);
    }
    return call<Page>('GET', '/budget-ledgers', role, undefined, { ...applied, page, size: PAGE_SIZE });
  }, [applied, page, role]);

  const set = (name: keyof Cond, value: string | number) => {
    setForm({ ...form, [name]: value });
  };

  const search = () => {
    if (!form.ledgerType || !form.dateFrom || !form.dateTo) {
      setMessage('장부 종류와 조회 기간(시작·종료)을 선택해 주세요.');
      return;
    }
    if (form.dateFrom > form.dateTo) {
      setMessage('조회 기간의 시작일이 종료일보다 늦습니다.');
      return;
    }
    setMessage('');
    setPage(0);
    setApplied({ ...form });
    notify('장부를 조회했습니다.');
  };

  const reset = () => {
    setForm(EMPTY);
    setApplied(null);
    setMessage('');
    setPage(0);
  };

  const rows: Row[] = ((data?.items?.[0]?.rows as Row[] | undefined) ?? []);
  const total = data?.total ?? 0;
  const keys = rows.length > 0 ? Object.keys(rows[0]) : [];
  const columns: Column[] = keys.map((key) => ({
    key,
    label: LABELS[key] ?? key,
    render: (row: Row) => cellOf(key, row[key], role),
  }));
  const isCashbook = form.ledgerType === '자금출납장';

  return (
    <div className="bento">
      <section className="box span-8">
        <h2>예산 장부</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="장부 종류" required>
            <Select value={form.ledgerType} onChange={(v) => set('ledgerType', v)} options={LEDGER_TYPES} />
          </Field>
          <Field label="조회 기간 시작" required>
            <DateInput value={form.dateFrom} onChange={(v) => set('dateFrom', v)} />
          </Field>
          <Field label="조회 기간 종료" required>
            <DateInput value={form.dateTo} onChange={(v) => set('dateTo', v)} />
          </Field>
          {isCashbook ? (
            <Field label="조회 구분">
              <Select value={form.cashbookScope} onChange={(v) => set('cashbookScope', v)} options={SCOPES} />
            </Field>
          ) : (
            <Field label="조회 형태">
              <Select value={form.viewForm} onChange={(v) => set('viewForm', v)} options={VIEW_FORMS} />
            </Field>
          )}
          <Field label="프로젝트">
            <LookupSelect table="project" role={role} value={form.projectId} onChange={(v) => set('projectId', v)} />
          </Field>
          <Field label="작성자">
            <LookupSelect table="employee" role={role} value={form.authorId} onChange={(v) => set('authorId', v)} />
          </Field>
          <Field label="거래처 계좌">
            <LookupSelect
              table="partner_account"
              role={role}
              value={form.partnerAccountId}
              onChange={(v) => set('partnerAccountId', v)}
            />
          </Field>
        </Filters>
        {message ? <ErrorText text={message} /> : null}
        {error ? <ErrorText text={error} /> : null}
        <Band total={total} />
        <DataTable
          columns={columns}
          rows={rows}
          onRowClick={(row) => setDetail(row)}
          empty={applied ? (loading ? '불러오는 중입니다.' : '조회 결과가 없습니다.') : '장부 종류와 기간을 선택하고 조회해 주세요.'}
        />
        <Pager page={page} size={PAGE_SIZE} total={total} onPage={setPage} />
      </section>
      <section className="box span-4">
        <h2>조회 요약</h2>
        <Tiles
          items={[
            ['조회 건수', <Num value={total} />],
            ['현재 쪽 건수', <Num value={rows.length} />],
          ]}
        />
      </section>
      {detail ? (
        <Drawer title="장부 상세" onClose={() => setDetail(null)}>
          <Pairs items={Object.keys(detail).map((key): [string, ReactNode] => [LABELS[key] ?? key, cellOf(key, detail[key], role)])} />
        </Drawer>
      ) : null}
    </div>
  );
}
